    [Theory]
    [InlineData(LoyaltyTier.Green, 4_999, 4_750)]    // 5% of 49.99 = 2.4995 -> 2.49
    [InlineData(LoyaltyTier.Gold, 4_999, 4_650)]     // 7% = 3.4993 -> 3.49
